/**
 * Uploader for the product-guide media set.
 *
 * Mirrors <repo-root>/../media-src/guides/<slug>/* to
 *   <S3_UPLOAD_PREFIX>/guides/<slug>/<file>
 * with stable keys and a 1-year immutable cache, so a re-run overwrites in
 * place and the URLs `client/lib/templateMedia.ts` builds never change.
 *
 * Deliberately a sibling of uploadTemplateMedia.ts rather than a flag on it.
 * The two sets are re-generated by different scripts on different schedules —
 * template assets when a design changes, guide assets when a *flow* changes —
 * and sharing one uploader would mean a screenshot re-capture could overwrite a
 * template cover, or a `--only=` typo could clear the wrong prefix.
 *
 * Usage (from /server):
 *   npm run upload:guide-media
 *   npm run upload:guide-media -- --dry
 *   npm run upload:guide-media -- --only=happy-rakshabandhan-to-sister
 */
import fs from "fs";
import path from "path";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { env } from "../config/env";

const DRY = process.argv.includes("--dry");
const ONLY = (process.argv.find((a) => a.startsWith("--only=")) || "").split("=")[1] || "";

/** Source of truth, intentionally outside the repos. */
const MEDIA_SRC = path.resolve(process.cwd(), "../media-src/guides");

const KEY_ROOT = `${(env.S3_UPLOAD_PREFIX || "gifts-media").replace(/\/+$/, "")}/guides`;

const CONTENT_TYPES: Record<string, string> = {
  ".mp4": "video/mp4",
  ".webm": "video/webm",
  ".webp": "image/webp",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".svg": "image/svg+xml",
  ".vtt": "text/vtt",
};

function discoverSlugs(): string[] {
  if (!fs.existsSync(MEDIA_SRC)) return [];
  return fs
    .readdirSync(MEDIA_SRC, { withFileTypes: true })
    .filter((e) => e.isDirectory() && !e.name.startsWith("."))
    .map((e) => e.name)
    .sort();
}

function publicBase(): string {
  if (env.S3_PUBLIC_BASE_URL) return `${env.S3_PUBLIC_BASE_URL.replace(/\/+$/, "")}/${KEY_ROOT}`;
  return `https://${env.S3_BUCKET_NAME}.s3.${env.S3_REGION}.amazonaws.com/${KEY_ROOT}`;
}

const mb = (b: number) => `${(b / 1048576).toFixed(2)} MB`;

async function main() {
  if (!env.S3_REGION || !env.S3_BUCKET_NAME || !env.S3_ACCESS_KEY_ID || !env.S3_SECRET_ACCESS_KEY) {
    console.error(
      "❌ S3 is not configured. Set S3_REGION, S3_BUCKET_NAME, S3_ACCESS_KEY_ID, S3_SECRET_ACCESS_KEY in server/.env",
    );
    process.exit(1);
  }

  // A loud guard rather than a silent success. The credentials that shipped in
  // server/.env point at `gifts-media-prod-123`, a bucket in an AWS account that
  // no longer exists — every key there answers 403 AllAccessDisabled and its IAM
  // key answers InvalidAccessKeyId. Uploading "successfully" into a dead bucket
  // and then wondering why the site shows broken video is a genuinely expensive
  // afternoon, so refuse it outright.
  if (env.S3_BUCKET_NAME === "gifts-media-prod-123") {
    console.error("❌ S3_BUCKET_NAME is still the OLD, DEAD bucket: gifts-media-prod-123");
    console.error("   That AWS account is closed. The live bucket is `subhsandesh-prod`,");
    console.error("   fronted by https://cdn.subhsandesh.in, written by IAM user `dilse-s3`.");
    console.error("   Set these in server/.env from /opt/dilse/.env.backend on the prod box:");
    console.error("     S3_BUCKET_NAME=subhsandesh-prod");
    console.error("     S3_PUBLIC_BASE_URL=https://cdn.subhsandesh.in");
    console.error("     S3_ACCESS_KEY_ID=...   S3_SECRET_ACCESS_KEY=...");
    process.exit(1);
  }

  if (!fs.existsSync(MEDIA_SRC)) {
    console.error(`❌ Media source not found: ${MEDIA_SRC}`);
    console.error("   Run ./scripts/compress-guide-videos.sh from the repo root first.");
    process.exit(1);
  }

  const known = discoverSlugs();
  const slugs = ONLY ? known.filter((s) => s === ONLY) : known;
  if (slugs.length === 0) {
    console.error(`❌ Nothing to upload. --only=${ONLY || "(none)"}. Found: ${known.join(", ") || "(none)"}`);
    process.exit(1);
  }

  const s3 = new S3Client({
    region: env.S3_REGION,
    credentials: {
      accessKeyId: env.S3_ACCESS_KEY_ID,
      secretAccessKey: env.S3_SECRET_ACCESS_KEY,
    },
  });

  console.log(`\n🎬  Guide media → S3`);
  console.log(`   bucket : ${env.S3_BUCKET_NAME} (${env.S3_REGION})`);
  console.log(`   prefix : ${KEY_ROOT}/`);
  console.log(`   source : ${MEDIA_SRC}${DRY ? "   [DRY RUN]" : ""}\n`);

  let count = 0;
  let bytes = 0;

  for (const slug of slugs) {
    const dir = path.join(MEDIA_SRC, slug);
    const files = fs
      .readdirSync(dir, { withFileTypes: true })
      .filter((e) => e.isFile() && !e.name.startsWith("."))
      .map((e) => e.name)
      .sort();

    console.log(`  ${slug}`);

    for (const file of files) {
      const ext = path.extname(file).toLowerCase();
      const contentType = CONTENT_TYPES[ext];
      if (!contentType) {
        console.log(`    – ${file}  (skipped, unknown type ${ext})`);
        continue;
      }

      const body = fs.readFileSync(path.join(dir, file));
      const key = `${KEY_ROOT}/${slug}/${file}`;

      if (!DRY) {
        await s3.send(
          new PutObjectCommand({
            Bucket: env.S3_BUCKET_NAME,
            Key: key,
            Body: body,
            ContentType: contentType,
            // Stable keys + immutable: a browser and the CDN fetch each object
            // exactly once, ever. Re-running this script replaces the object at
            // the same URL, so a CDN invalidation is the only thing needed to
            // push a correction — not a new filename and a code change.
            CacheControl: "public, max-age=31536000, immutable",
          }),
        );
      }

      count += 1;
      bytes += body.length;
      console.log(`    ✓ ${file.padEnd(46)} ${mb(body.length).padStart(9)}`);
    }
  }

  console.log(`\n   ${DRY ? "would upload" : "uploaded"} ${count} objects · ${mb(bytes)}`);
  console.log(`   public base: ${publicBase()}/\n`);
}

main().catch((err) => {
  console.error("❌ Upload failed:", err);
  process.exit(1);
});
